import React, { useEffect, useState } from 'react';
import MatrixRain from '../components/MatrixRain.jsx';
import GlitchTitle from '../components/GlitchTitle.jsx';
import LanguageCard from '../components/LanguageCard.jsx';
import { LANGUAGE_CARDS } from '../data/languageCards.js';

export default function WelcomePage({ onSelectLanguage }) {
    const [titleVisible, setTitleVisible] = useState(false);
    const [currentTime, setCurrentTime] = useState(new Date());
    const [activeLearners, setActiveLearners] = useState(2347);
    const [systemLogs, setSystemLogs] = useState([
        '> SYSTEM BOOT: v2.0.4 SECURE',
        '> NEURAL ENGINE: ONLINE',
        '> WAITING FOR LANGUAGE SELECTION'
    ]);

    // Animate title entrance
    useEffect(() => {
        const t = setTimeout(() => setTitleVisible(true), 100);
        return () => clearTimeout(t);
    }, []);

    // Real-time clock
    useEffect(() => {
        const interval = setInterval(() => {
            setCurrentTime(new Date());
        }, 1000);
        return () => clearInterval(interval);
    }, []);

    // Simulate active learners fluctuation and rotating logs
    useEffect(() => {
        const learnerInterval = setInterval(() => {
            setActiveLearners(prev => {
                const change = Math.floor(Math.random() * 21) - 10; // -10 to +10
                return Math.max(1200, Math.min(3800, prev + change));
            });
        }, 8000);

        const logInterval = setInterval(() => {
            const logMessages = [
                '> SCANNING TRAFFIC: 1.4 GB/S',
                '> ENCRYPTION LAYER: ACTIVE',
                '> CYBER DEFENSE: STANDBY',
                '> KERNEL INTEGRITY: VERIFIED',
                '> AI CORE: RESPONDING',
                '> USER SESSION: SECURE'
            ];
            setSystemLogs(prev => {
                const newLog = logMessages[Math.floor(Math.random() * logMessages.length)];
                return [newLog, ...prev.slice(0, 2)];
            });
        }, 5000);

        return () => {
            clearInterval(learnerInterval);
            clearInterval(logInterval);
        };
    }, []);

    // Format time HH:MM:SS
    const formattedTime = currentTime.toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
    });

    // Calculate total modules across languages (if available)
    const totalModules = LANGUAGE_CARDS.reduce((acc, lang) => {
        return acc + (lang.modulesCount || 24); // fallback value
    }, 0);

    return (
        <div style={{
            position: 'relative',
            minHeight: '100vh',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'flex-start',
            overflowY: 'auto',
            overflowX: 'hidden',
            background: 'var(--bg-primary)',
            paddingBottom: '32px'
        }}>
            <MatrixRain />

            {/* Radial glow center (background effect) */}
            <div style={{
                position: 'fixed',
                top: '50%',
                left: '50%',
                transform: 'translate(-50%, -50%)',
                width: 700,
                height: 700,
                borderRadius: '50%',
                background: 'radial-gradient(circle, rgba(0,245,255,0.05) 0%, transparent 75%)',
                pointerEvents: 'none',
                zIndex: 0
            }} />

            {/* Header Section */}
            <div style={{
                position: 'relative',
                zIndex: 2,
                textAlign: 'center',
                marginTop: '48px',
                marginBottom: '32px',
                opacity: titleVisible ? 1 : 0,
                transform: titleVisible ? 'translateY(0)' : 'translateY(-20px)',
                transition: 'all 0.8s cubic-bezier(0.34,1.56,0.64,1)',
            }}>
                <div style={{
                    fontFamily: 'var(--font-mono)',
                    fontSize: 11,
                    letterSpacing: '0.3em',
                    color: 'var(--text-muted)',
                    marginBottom: 16,
                    textTransform: 'uppercase',
                }}>
                    <span style={{ color: 'var(--accent-cyan)' }}>▸</span> CYBERCODE LEARNING SYSTEM v2.0.4
                </div>

                <GlitchTitle text="CYBERCODE" />

                <div style={{
                    fontFamily: 'var(--font-ui)',
                    fontWeight: 300,
                    fontSize: 18,
                    color: 'var(--text-secondary)',
                    letterSpacing: '0.2em',
                    marginTop: 8,
                    textTransform: 'uppercase',
                }}>
                    SELECT YOUR LANGUAGE / BEGIN TRAINING
                </div>

                <div style={{
                    margin: '20px auto 0',
                    width: 240,
                    height: 1,
                    background: 'linear-gradient(90deg, transparent, var(--accent-cyan), transparent)',
                    opacity: 0.6,
                }} />
            </div>

            {/* Language Cards */}
            <div style={{
                position: 'relative',
                zIndex: 2,
                display: 'flex',
                gap: 28,
                flexWrap: 'wrap',
                justifyContent: 'center',
                padding: '0 20px',
                marginBottom: '40px'
            }}>
                {LANGUAGE_CARDS.map((lang, i) => (
                    <LanguageCard
                        key={lang.id}
                        lang={lang}
                        onSelect={onSelectLanguage}
                        delay={300 + i * 150}
                    />
                ))}
            </div>

            {/* ===== ADDED INFO SECTIONS ===== */}

            {/* System Stats Grid */}
            <div style={{
                position: 'relative',
                zIndex: 2,
                display: 'flex',
                flexWrap: 'wrap',
                justifyContent: 'center',
                gap: '20px',
                maxWidth: '900px',
                margin: '20px auto 32px',
                padding: '0 20px'
            }}>
                {/* Stat Card 1: Live Clock */}
                <div style={{
                    background: 'rgba(0, 20, 30, 0.6)',
                    backdropFilter: 'blur(4px)',
                    border: '1px solid rgba(0, 245, 255, 0.25)',
                    borderRadius: '12px',
                    padding: '16px 24px',
                    minWidth: '140px',
                    textAlign: 'center',
                    fontFamily: 'var(--font-mono)',
                    boxShadow: '0 0 15px rgba(0,245,255,0.1)',
                    transition: 'all 0.2s'
                }}>
                    <div style={{ fontSize: '11px', color: 'var(--text-muted)', letterSpacing: '2px', marginBottom: '8px' }}>
                        SYS TIME
                    </div>
                    <div style={{ fontSize: '24px', fontWeight: 'bold', color: 'var(--accent-cyan)', textShadow: '0 0 5px cyan' }}>
                        {formattedTime}
                    </div>
                    <div style={{ fontSize: '10px', color: 'var(--text-secondary)', marginTop: '6px' }}>
                        UTC+0 // SECURE
                    </div>
                </div>

                {/* Stat Card 2: Active Learners */}
                <div style={{
                    background: 'rgba(0, 20, 30, 0.6)',
                    backdropFilter: 'blur(4px)',
                    border: '1px solid rgba(0, 245, 255, 0.25)',
                    borderRadius: '12px',
                    padding: '16px 24px',
                    minWidth: '140px',
                    textAlign: 'center',
                    fontFamily: 'var(--font-mono)',
                    boxShadow: '0 0 15px rgba(0,245,255,0.1)'
                }}>
                    <div style={{ fontSize: '11px', color: 'var(--text-muted)', letterSpacing: '2px', marginBottom: '8px' }}>
                        ACTIVE USERS
                    </div>
                    <div style={{ fontSize: '24px', fontWeight: 'bold', color: 'var(--accent-cyan)' }}>
                        {activeLearners.toLocaleString()}
                    </div>
                    <div style={{ fontSize: '10px', color: 'var(--text-secondary)', marginTop: '6px' }}>
                        ◉ REAL-TIME TRAFFIC
                    </div>
                </div>

                {/* Stat Card 3: Total Modules */}
                <div style={{
                    background: 'rgba(0, 20, 30, 0.6)',
                    backdropFilter: 'blur(4px)',
                    border: '1px solid rgba(0, 245, 255, 0.25)',
                    borderRadius: '12px',
                    padding: '16px 24px',
                    minWidth: '140px',
                    textAlign: 'center',
                    fontFamily: 'var(--font-mono)'
                }}>
                    <div style={{ fontSize: '11px', color: 'var(--text-muted)', letterSpacing: '2px', marginBottom: '8px' }}>
                        TOTAL MODULES
                    </div>
                    <div style={{ fontSize: '24px', fontWeight: 'bold', color: 'var(--accent-cyan)' }}>
                        {totalModules}
                    </div>
                    <div style={{ fontSize: '10px', color: 'var(--text-secondary)', marginTop: '6px' }}>
                        ADVANCED TRACKS
                    </div>
                </div>

                {/* Stat Card 4: System Integrity */}
                <div style={{
                    background: 'rgba(0, 20, 30, 0.6)',
                    backdropFilter: 'blur(4px)',
                    border: '1px solid rgba(0, 245, 255, 0.25)',
                    borderRadius: '12px',
                    padding: '16px 24px',
                    minWidth: '140px',
                    textAlign: 'center',
                    fontFamily: 'var(--font-mono)'
                }}>
                    <div style={{ fontSize: '11px', color: 'var(--text-muted)', letterSpacing: '2px', marginBottom: '8px' }}>
                        INTEGRITY
                    </div>
                    <div style={{ fontSize: '24px', fontWeight: 'bold', color: 'var(--accent-cyan)' }}>
                        99.98%
                    </div>
                    <div style={{ fontSize: '10px', color: 'var(--text-secondary)', marginTop: '6px' }}>
                        ENCRYPTED CHAIN
                    </div>
                </div>
            </div>

            {/* Console Log Panel & Extra Info Row */}
            <div style={{
                position: 'relative',
                zIndex: 2,
                display: 'flex',
                flexWrap: 'wrap',
                justifyContent: 'center',
                gap: '24px',
                width: '100%',
                maxWidth: '1000px',
                margin: '0 auto 48px',
                padding: '0 20px'
            }}>
                {/* System Console (Live Logs) */}
                <div style={{
                    flex: '1',
                    minWidth: '240px',
                    background: 'rgba(0, 0, 0, 0.65)',
                    backdropFilter: 'blur(5px)',
                    border: '1px solid rgba(0, 245, 255, 0.3)',
                    borderRadius: '12px',
                    padding: '16px 20px',
                    fontFamily: 'var(--font-mono)',
                    boxShadow: '0 4px 20px rgba(0,0,0,0.5)'
                }}>
                    <div style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: '8px',
                        marginBottom: '14px',
                        borderBottom: '1px solid rgba(0,245,255,0.3)',
                        paddingBottom: '8px'
                    }}>
                        <span style={{ color: 'var(--accent-cyan)', fontSize: '14px' }}>▶</span>
                        <span style={{ fontSize: '12px', letterSpacing: '1px', color: 'var(--text-secondary)' }}>
              SYSTEM CONSOLE // LIVE FEED
            </span>
                        <span style={{ marginLeft: 'auto', fontSize: '10px', color: 'var(--accent-cyan)', animation: 'blink 1.5s infinite' }}>
              ACTIVE
            </span>
                    </div>
                    {systemLogs.map((log, idx) => (
                        <div key={idx} style={{
                            fontSize: '11px',
                            color: idx === 0 ? 'var(--accent-cyan)' : 'var(--text-muted)',
                            marginBottom: '8px',
                            fontFamily: 'monospace',
                            opacity: idx === 0 ? 1 : 0.7,
                            letterSpacing: '0.3px'
                        }}>
                            {log}
                        </div>
                    ))}
                    <div style={{ marginTop: '8px', fontSize: '10px', color: 'rgba(0,245,255,0.6)' }}>
                        > _ awaiting input_
                    </div>
                </div>

                {/* Tech Specs / Info Panel */}
                <div style={{
                    flex: '1',
                    minWidth: '240px',
                    background: 'rgba(0, 0, 0, 0.65)',
                    backdropFilter: 'blur(5px)',
                    border: '1px solid rgba(0, 245, 255, 0.3)',
                    borderRadius: '12px',
                    padding: '16px 20px',
                    fontFamily: 'var(--font-ui)'
                }}>
                    <div style={{
                        fontSize: '11px',
                        color: 'var(--accent-cyan)',
                        letterSpacing: '1.5px',
                        marginBottom: '14px',
                        borderBottom: '1px solid rgba(0,245,255,0.3)',
                        paddingBottom: '8px'
                    }}>
                        ⚡ CORE FEATURES
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px' }}>
                            <span style={{ color: 'var(--text-muted)' }}>NEURAL ASSIST</span>
                            <span style={{ color: 'var(--accent-cyan)' }}>ONLINE</span>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px' }}>
                            <span style={{ color: 'var(--text-muted)' }}>REAL-TIME DEBUGGER</span>
                            <span style={{ color: 'var(--accent-cyan)' }}>READY</span>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px' }}>
                            <span style={{ color: 'var(--text-muted)' }}>CYBER RANKING</span>
                            <span style={{ color: 'var(--accent-cyan)' }}>GLOBAL #312</span>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px' }}>
                            <span style={{ color: 'var(--text-muted)' }}>LATEST PATCH</span>
                            <span style={{ color: 'var(--accent-cyan)' }}>v2.0.4_secure</span>
                        </div>
                        <div style={{ marginTop: '6px', height: '2px', background: 'linear-gradient(90deg, transparent, var(--accent-cyan), transparent)' }} />
                        <div style={{ fontSize: '11px', color: 'var(--text-secondary)', textAlign: 'center', marginTop: '4px' }}>
                            🔒 QUANTUM ENCRYPTED SESSION
                        </div>
                    </div>
                </div>
            </div>

            {/* Footer (restructured from absolute to flex layout) */}
            <div style={{
                position: 'relative',
                zIndex: 2,
                marginTop: 'auto',
                marginBottom: '24px',
                fontFamily: 'var(--font-mono)',
                fontSize: 11,
                color: 'var(--text-muted)',
                letterSpacing: '0.15em',
                display: 'flex',
                gap: 32,
                alignItems: 'center',
                flexWrap: 'wrap',
                justifyContent: 'center',
                borderTop: '1px solid rgba(0,245,255,0.15)',
                paddingTop: '20px',
                width: '100%'
            }}>
                <span>SYS:ONLINE</span>
                <span style={{ color: 'var(--accent-cyan)', animation: 'blink 1.5s infinite' }}>■</span>
                <span>MODULES: C // PYTHON</span>
                <span style={{ color: 'var(--accent-cyan)', animation: 'blink 1.5s infinite' }}>■</span>
                <span>STATUS: READY</span>
                <span style={{ color: 'var(--accent-cyan)', animation: 'blink 1.5s infinite' }}>■</span>
                <span>UPTIME: 14D 8H 23M</span>
            </div>
        </div>
    );
}
